# The brand palette. Colour values live in R/palette-brand-data.R, generated by
# data-raw/palette-brand.R; the design rules are in the brand palette manifesto.

brand_l <- 63
brand_c <- 60
brand_harmony <- 0.35

#' Brand colours
#'
#' The 24 brand swatches. `brand_colours` holds the original swatches for
#' logos, tables and one-off accents. `brand_colours_harmonised` holds the
#' same hues with lightness and chroma pulled towards L 63, C 60; plots use
#' these. `brand_gradients`, `brand_diverging` and `brand_ramps` hold the
#' 9-stop sequential, diverging and single-hue palettes.
#'
#' @format Named character vectors of hex codes (`brand_colours`,
#'   `brand_colours_harmonised`) and named lists of 9 hex codes each
#'   (`brand_gradients`, `brand_diverging`, `brand_ramps`).
#' @name brand_colours
#' @aliases brand_colours_harmonised brand_gradients brand_diverging brand_ramps
#' @export brand_colours brand_colours_harmonised brand_gradients brand_diverging brand_ramps
#' @examples
#' brand_colours[["teal"]]
#' brand_colours_harmonised[["teal"]]
#' names(brand_gradients)
NULL

#' Brand discrete palette
#'
#' Drop-in replacement for [scales::pal_hue()]. Spaces `n` target hues evenly
#' from `h_start` and snaps each to the nearest unused hue of the 13-hue brand
#' wheel, so group k lands on roughly the same hue as in ggplot2's default.
#' Above 13 groups it falls back to evenly spaced hues at brand lightness and
#' chroma.
#'
#' @param h_start Starting hue in degrees. 18 is brand red; `scales::pal_hue()`
#'   starts at 15.
#' @param direction `1` for increasing hue, `-1` for decreasing.
#' @param harmonise If `TRUE`, return harmonised colours; if `FALSE`, the
#'   original swatches for the same selection.
#' @return A function of `n` returning `n` hex codes.
#' @export
#' @examples
#' brand_pal()(5)
#' brand_pal(h_start = 145, direction = -1)(3)
brand_pal <- function(h_start = 18, direction = 1, harmonise = TRUE) {
  force(h_start)
  force(direction)
  force(harmonise)
  function(n) {
    targets <- (h_start + direction * 360 * (seq_len(n) - 1) / n) %% 360
    if (n > length(brand_wheel_hues)) {
      return(brand_hcl(targets, brand_c, brand_l))
    }
    key <- brand_snap(targets, brand_wheel_hues)
    source <- if (harmonise) brand_colours_harmonised else brand_colours
    unname(source[key])
  }
}

brand_snap <- function(targets, wheel) {
  d <- abs(outer(targets, unname(wheel), \(a, b) (a - b + 180) %% 360 - 180))
  pick <- integer(length(targets))
  for (i in seq_along(targets)) {
    m <- which(d == min(d), arr.ind = TRUE)[1, ]
    pick[m[1]] <- m[2]
    d[m[1], ] <- Inf
    d[, m[2]] <- Inf
  }
  names(wheel)[pick]
}

#' Brand colours from HCL coordinates
#'
#' Converts hue, chroma and luminance (polar CIELUV, as in [grDevices::hcl()])
#' to hex. Out-of-gamut colours have their chroma lowered in steps of 0.5
#' until they fit, instead of returning `NA`.
#'
#' @param h Hue in degrees.
#' @param c Chroma.
#' @param l Luminance, 0 to 100.
#' @return A character vector of hex codes.
#' @export
#' @examples
#' brand_hcl(h = 200, c = 40, l = 70)
brand_hcl <- function(h, c, l) {
  n <- max(length(h), length(c), length(l))
  h <- rep_len(h, n) %% 360
  c <- pmax(rep_len(c, n), 0)
  l <- pmin(pmax(rep_len(l, n), 0), 100)
  out <- grDevices::hcl(h, c, l, fixup = FALSE)
  while (anyNA(out)) {
    bad <- is.na(out)
    c[bad] <- pmax(c[bad] - 0.5, 0)
    out[bad] <- grDevices::hcl(h[bad], c[bad], l[bad], fixup = FALSE)
  }
  out
}

#' Harmonise colours to the brand
#'
#' Keeps each colour's hue and pulls its lightness and chroma towards the
#' brand level, keeping `strength` of the original deviation. This is the pull
#' that produced [brand_colours_harmonised]. Needs the colorspace package.
#'
#' @param x Hex codes, optionally named.
#' @param l,c Target luminance and chroma.
#' @param strength Share of the original deviation to keep: `0` flattens
#'   fully, `1` leaves the colours untouched.
#' @return Hex codes with the names of `x`.
#' @export
#' @examples
#' if (rlang::is_installed("colorspace")) brand_harmonise(c(accent = "#FF0066"))
brand_harmonise <- function(x, l = brand_l, c = brand_c, strength = brand_harmony) {
  rlang::check_installed("colorspace", reason = "to convert hex codes to HCL.")
  hcl <- colorspace::hex2RGB(x) |>
    methods::as("polarLUV") |>
    colorspace::coords()
  brand_hcl(hcl[, "H"], c + strength * (hcl[, "C"] - c), l + strength * (hcl[, "L"] - l)) |>
    rlang::set_names(names(x))
}

#' Brand gradients
#'
#' `brand_gradient()` returns the 9 stops of a sequential, diverging or
#' single-hue palette. `brand_ramp()` returns the single-hue ramp of one
#' swatch. `brand_grad_pal()` returns a palette function for values in
#' `[0, 1]`, like [scales::pal_gradient_n()].
#'
#' Sequential gradients run light (low) to dark (high), the opposite of
#' ggplot2's default; `reverse = TRUE` matches ggplot2.
#'
#' @param palette A name from `brand_gradients`, `brand_diverging` or
#'   `brand_colours`.
#' @param colour A name from `brand_colours`.
#' @param reverse If `TRUE`, reverse the order of the stops.
#' @return `brand_gradient()` and `brand_ramp()` return 9 hex codes;
#'   `brand_grad_pal()` returns a function.
#' @export
#' @examples
#' brand_gradient("ocean")
#' brand_ramp("purple")
#' brand_grad_pal("sunset")(seq(0, 1, length.out = 10))
brand_gradient <- function(palette = "ocean", reverse = FALSE) {
  cols <- palette_lookup(palette, list(brand_gradients, brand_diverging, brand_ramps))
  if (reverse) rev(cols) else cols
}

#' @rdname brand_gradient
#' @export
brand_ramp <- function(colour) {
  palette_lookup(colour, list(brand_ramps))
}

#' @rdname brand_gradient
#' @export
brand_grad_pal <- function(palette = "ocean", reverse = FALSE) {
  scales::pal_gradient_n(brand_gradient(palette, reverse))
}

#' Brand scales for ggplot2
#'
#' Drop-in replacements for ggplot2's default colour and fill scales.
#'
#' | ggplot2 default | brand replacement |
#' |---|---|
#' | `scale_colour_discrete()` | `scale_colour_brand_d()` |
#' | `scale_fill_continuous()` | `scale_fill_brand_c("ocean")` |
#' | `scale_fill_binned()` | `scale_fill_brand_b("ocean")` |
#' | `scale_fill_gradient2(midpoint = m)` | `scale_fill_brand_div("red_blue", midpoint = m)` |
#'
#' @inheritParams brand_pal
#' @inheritParams brand_gradient
#' @param ... Passed to the underlying ggplot2 scale, such as `name`,
#'   `limits`, `breaks` or `na.value`.
#' @param midpoint Data value mapped to the neutral centre.
#' @param aesthetics Aesthetics the scale applies to.
#' @return A ggplot2 scale.
#' @name scale_brand
#' @examples
#' p <- ggplot2::ggplot(ggplot2::mpg, ggplot2::aes(displ, hwy, colour = class)) +
#'   ggplot2::geom_point()
#' p + scale_colour_brand_d()
#'
#' ggplot2::ggplot(ggplot2::faithfuld, ggplot2::aes(waiting, eruptions, fill = density)) +
#'   ggplot2::geom_raster() +
#'   scale_fill_brand_c("teal", reverse = TRUE)
NULL

#' @rdname scale_brand
#' @export
scale_colour_brand_d <- function(..., h_start = 18, direction = 1, harmonise = TRUE, aesthetics = "colour") {
  palette_scale_d(aesthetics, brand_pal(h_start, direction, harmonise), ...)
}

#' @rdname scale_brand
#' @export
scale_fill_brand_d <- function(..., h_start = 18, direction = 1, harmonise = TRUE, aesthetics = "fill") {
  palette_scale_d(aesthetics, brand_pal(h_start, direction, harmonise), ...)
}

#' @rdname scale_brand
#' @export
scale_colour_brand_c <- function(palette = "ocean", ..., reverse = FALSE, aesthetics = "colour") {
  palette_scale_c(aesthetics, brand_gradient(palette, reverse), ...)
}

#' @rdname scale_brand
#' @export
scale_fill_brand_c <- function(palette = "ocean", ..., reverse = FALSE, aesthetics = "fill") {
  palette_scale_c(aesthetics, brand_gradient(palette, reverse), ...)
}

#' @rdname scale_brand
#' @export
scale_colour_brand_b <- function(palette = "ocean", ..., reverse = FALSE, aesthetics = "colour") {
  palette_scale_b(aesthetics, brand_gradient(palette, reverse), ...)
}

#' @rdname scale_brand
#' @export
scale_fill_brand_b <- function(palette = "ocean", ..., reverse = FALSE, aesthetics = "fill") {
  palette_scale_b(aesthetics, brand_gradient(palette, reverse), ...)
}

#' @rdname scale_brand
#' @export
scale_colour_brand_div <- function(palette = "red_blue", ..., midpoint = 0, reverse = FALSE, aesthetics = "colour") {
  palette_scale_div(aesthetics, brand_gradient(palette, reverse), ..., midpoint = midpoint)
}

#' @rdname scale_brand
#' @export
scale_fill_brand_div <- function(palette = "red_blue", ..., midpoint = 0, reverse = FALSE, aesthetics = "fill") {
  palette_scale_div(aesthetics, brand_gradient(palette, reverse), ..., midpoint = midpoint)
}

#' @rdname scale_brand
#' @export
scale_color_brand_d <- scale_colour_brand_d

#' @rdname scale_brand
#' @export
scale_color_brand_c <- scale_colour_brand_c

#' @rdname scale_brand
#' @export
scale_color_brand_b <- scale_colour_brand_b

#' @rdname scale_brand
#' @export
scale_color_brand_div <- scale_colour_brand_div

#' Make brand the default ggplot2 palette
#'
#' Sets ggplot2's `ggplot2.discrete.*`, `ggplot2.continuous.*` and
#' `ggplot2.binned.*` options, so every plot uses brand without a `scale_*()`
#' call. [reset_ggplot2_palette()] switches back.
#'
#' @inheritParams brand_pal
#' @param continuous Palette for continuous and binned scales.
#' @return The previous option values, invisibly.
#' @export
#' @examples
#' use_brand_palette(continuous = "ocean")
#' ggplot2::ggplot(ggplot2::mpg, ggplot2::aes(displ, hwy, colour = class)) +
#'   ggplot2::geom_point()
#' reset_ggplot2_palette()
use_brand_palette <- function(h_start = 18, harmonise = TRUE, continuous = "ocean") {
  brand_gradient(continuous)
  palette_set_options(
    colour_d = \(...) scale_colour_brand_d(..., h_start = h_start, harmonise = harmonise),
    fill_d   = \(...) scale_fill_brand_d(..., h_start = h_start, harmonise = harmonise),
    colour_c = \(...) scale_colour_brand_c(continuous, ...),
    fill_c   = \(...) scale_fill_brand_c(continuous, ...),
    colour_b = \(...) scale_colour_brand_b(continuous, ...),
    fill_b   = \(...) scale_fill_brand_b(continuous, ...)
  )
}
